CREATE OR REPLACE FUNCTION ECAMS.MASTER_UNIQUE
  (SYSCD  IN VARCHAR2,
   RSRCCD IN VARCHAR2,
   JOBCD  IN VARCHAR2,
   DIRPATH IN VARCHAR2,
   RSRCNAME IN VARCHAR2)
RETURN INTEGER
IS
  VCNT INT := 0;

BEGIN
    SELECT COUNT(*)
      INTO VCNT
      FROM CMM0036
     WHERE CM_SYSCD=SYSCD
       AND CM_RSRCCD=RSRCCD
       AND SUBSTR(CM_INFO,49,1)='1';

    IF VCNT = 0 THEN
       RETURN 0;
    END IF;

    SELECT COUNT(*)
      INTO VCNT
      FROM CMM0070 B,CMR0020 A
     WHERE UPPER(A.CR_RSRCNAME)=UPPER(RSRCNAME)
       AND A.CR_STATUS<>'9'
       AND A.CR_REALSTA<>'9'
       AND A.CR_SYSCD=B.CM_SYSCD
       AND A.CR_DSNCD=B.CM_DSNCD
       AND CHGPATH(A.CR_SYSCD,A.CR_RSRCCD,A.CR_JOBCD,B.CM_DIRPATH)=CHGPATH(SYSCD,RSRCCD,JOBCD,DIRPATH);
   IF VCNT > 0 THEN
      RETURN 1;
   ELSE
      RETURN 0;
   END IF;
END;